## What to do

In the existing `refundCharge` function, find the block that handles `commission_split_reverse` (the proportional base+tip reversal). It has structure:

```ts
if (parentSplitData) {
  const parentSplit = parentSplitData as unknown as { id: string };
  // ... existing reversal logic with reverseIdemKey + reversalData ...
  commissionReversalId = reversal.id;
}
```

INSERT this NEW block IMMEDIATELY after `commissionReversalId = reversal.id;` and BEFORE the closing `}` of the `if (parentSplitData)` guard:

```ts
  // === S18 — Per-tax-line proportional reversal ===
  // Read all kind='tax_line' children of the parent split, reverse each proportionally.

  const refundRatio = args.refundCents / charge.amount_cents;

  // §S13.3 — types.ts regen pending; cast for tax_line children read.
  const fromUntypedTaxLines = supabase.from.bind(supabase) as unknown as (table: string) => {
    select: (cols: string) => {
      eq: (col: string, val: string) => {
        eq: (col2: string, val2: string) => Promise<{
          data: Array<{
            id: string;
            tax_line_id: string | null;
            jurisdiction: string | null;
            tax_amount_cents: number;
          }> | null;
          error: unknown;
        }>;
      };
    };
  };
  const { data: taxLinesData, error: taxLinesErr } = await fromUntypedTaxLines('commission_splits')
    .select('id, tax_line_id, jurisdiction, tax_amount_cents')
    .eq('parent_split_id', parentSplit.id)
    .eq('kind', 'tax_line');

  if (taxLinesErr) {
    logger.error(
      { refundId: refund.id, parent_split: parentSplit.id, err: taxLinesErr },
      'S18: failed to load tax_line children — tax reversal skipped (recoverable via reconciliation Leg 4)',
    );
  } else if (taxLinesData && taxLinesData.length > 0) {
    // Look up studio's primary location once (mirrors S17 pattern).
    const fromUntypedLocSelect = supabase.from.bind(supabase) as unknown as (table: string) => {
      select: (cols: string) => {
        eq: (col: string, val: string) => {
          limit: (n: number) => {
            maybeSingle: () => Promise<{ data: { id: string } | null; error: unknown }>;
          };
        };
      };
    };
    const { data: locationData } = await fromUntypedLocSelect('locations')
      .select('id')
      .eq('studio_id', args.studioId)
      .limit(1)
      .maybeSingle();

    const eventDate = new Date();
    const quarter = Math.floor(eventDate.getMonth() / 3) + 1;
    const period = `${eventDate.getFullYear()}-Q${quarter}`;

    for (const taxLine of taxLinesData) {
      const releaseTaxCents = cents(Math.round(taxLine.tax_amount_cents * refundRatio));
      if (releaseTaxCents <= 0) continue;

      // Reverse the tax_line commission_splits row.
      const reverseTaxIdemKey = idempotencyKeyFor('commission.tax_line.reverse', {
        parent_tax_line_split_id: taxLine.id,
        refund_id: refund.id,
      });
      const { error: reverseTaxErr } = await supabase.rpc(RPC.COMMISSION_SPLIT_TAX_LINE_REVERSE, {
        p_parent_tax_line_split_id: taxLine.id,
        p_release_tax_cents: releaseTaxCents,
        p_refund_id: refund.id,
        p_idempotency_key: reverseTaxIdemKey,
      });
      if (reverseTaxErr) {
        logger.error(
          { refundId: refund.id, tax_line_id: taxLine.id, err: reverseTaxErr },
          'S18: commission_split_tax_line_reverse failed — recoverable via reconciliation Leg 4',
        );
      }

      // Re-credit tax_remittance_ledger.
      if (locationData && taxLine.jurisdiction) {
        const releaseLedgerIdemKey = idempotencyKeyFor('tax_remittance.release', {
          refund_id: refund.id,
          jurisdiction: taxLine.jurisdiction,
        });
        const { error: ledgerErr } = await supabase.rpc(RPC.TAX_REMITTANCE_RELEASE, {
          p_studio_id: args.studioId,
          p_location_id: locationData.id,
          p_jurisdiction: taxLine.jurisdiction,
          p_period: period,
          p_release_amount_cents: releaseTaxCents,
          p_idempotency_key: releaseLedgerIdemKey,
          p_refund_id: refund.id,
        });
        if (ledgerErr) {
          logger.error(
            { refundId: refund.id, jurisdiction: taxLine.jurisdiction, period, err: ledgerErr },
            'S18: tax_remittance_release failed — recoverable via reconciliation Leg 4',
          );
        }
      }
    }
  }
```

If `cents` and `idempotencyKeyFor` aren't already imported in this file, add them to the existing imports from `@/lib/payments/contracts` and `@/lib/stripe/idempotency` respectively. Check the imports at the top of the file first.

## Verification

1. `pnpm typecheck 2>&1 | grep "lib/stripe/refunds"` — zero new errors.
2. `grep -c "RPC.COMMISSION_SPLIT_TAX_LINE_REVERSE" lib/stripe/refunds.ts` → 1+
